window.AISystem6SharedProjectDisksIndex = {"dtk":{"name":"未来通车之后","label":{"zh":"DTK 过渡机","en":"DTK Transition Kit"},"subject":"2020 年 Apple Developer Transition Kit（DTK）：一台没被销毁、还能开机的过渡机的第一人称遗迹报告，不是开箱 / 跑分测评","released":"2024-12","createdAt":"2026-07-04T14:59:00.000Z","exportedAt":"2026-10-03T21:50:00.000Z","words":2727,"files":11,"scraps":68},"ipad1":{"name":"初代 iPad 为什么只有 256MB 内存","label":{"zh":"初代 iPad","en":"Original iPad"},"subject":"初代 iPad（2010）与它的 256MB。不是维修记录，是一个小时候看过、一直没想明白的问题。","released":"2026-06","createdAt":"2026-04-25T12:00:00.000Z","exportedAt":"2026-09-25T12:00:00.000Z","words":1785,"files":6,"scraps":19},"m5ipad":{"name":"杀掉那个键盘","label":{"zh":"M5 iPad Pro","en":"M5 iPad Pro"},"subject":"2026 年的 M5 iPad Pro，和它替谁回答的那个老问题：一块平板，到底要不要长成一台电脑。不是开箱，不是参数复述，是把两台实机（13 寸 1TB、11 寸）和两个人（写稿的与拍摄的）真实用过的痕迹摊开来看。","released":"2026-05","createdAt":"2026-04-17T12:00:00.000Z","exportedAt":"2026-09-25T12:00:00.000Z","words":2632,"files":6,"scraps":21},"iphone17e":{"name":"iPhone 17e 浅粉色：其貌不扬，但很有料","label":{"zh":"iPhone 17e","en":"iPhone 17e"},"subject":"一台浅粉色的 iPhone 17e，和它身上那个反差的命题：看起来最不起眼的一台，反而是这一代最像「正常 iPhone」的一台。不是发布会文案，不是参数堆叠，是「看完就知道值不值」的口吻。","released":"2026-06","createdAt":"2026-05-31T12:00:00.000Z","exportedAt":"2026-09-23T17:15:00.000Z","words":2072,"files":4,"scraps":14},"bongo":{"name":"走向一整块玻璃：从 Project Bongo 看 iPhone 的终极演进","label":{"zh":"Project Bongo","en":"Project Bongo"},"subject":"iPhone 二十年里有一条一直没断的线：把机身上的开孔、接缝和机械件一个个去掉，最后只剩下一整块玻璃。固态按钮（Project Bongo）与 Liquid Glass 是这条线在结构与界面两端的动作。文章写的不是「苹果下一代长什么样」，是这条线从哪来、走到哪了、还差什么。","released":"","createdAt":"2025-10-19T12:00:00.000Z","exportedAt":"2026-09-24T14:00:00.000Z","words":1735,"files":4,"scraps":16},"glass":{"name":"玻璃与他们的产地","label":{"zh":"Liquid Glass","en":"Liquid Glass"},"subject":"苹果在 2025 年端出的 Liquid Glass，不是凭空冒出来的。它有一串可以点出来的祖先：Mac OS X 的 Aqua、Windows Vista 的 Aero Glass、iOS 7 的扁平化、Yosemite 与 Big Sur 的回归、Windows 11 与 visionOS 的中间态。这篇要写的不是「谁抄了谁」，而是每一代玻璃**是拿什么做的、为了什么在那儿**——以及为什么连音效都算在这条谱系里。","released":"","createdAt":"2025-07-20T12:00:00.000Z","exportedAt":"2026-09-23T17:25:00.000Z","words":1374,"files":4,"scraps":16},"ipad97":{"name":"iPad Pro 9.7：叛逆的另一种尺寸","label":{"zh":"iPad Pro 9.7","en":"iPad Pro 9.7"},"subject":"2016 年 3 月，苹果把「Pro」这个名字放到了一块 9.7 英寸的屏幕上。十二点九英寸那台是宣言，这一台是宣言缩小之后还能不能站住的问题。这篇不写「十年后还能不能用」，也不硬掰「生产力」——写的是叛逆心换一个尺寸以后变成了什么，以及它的名字后来去了哪。","released":"2026-07","createdAt":"2025-11-10T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1188,"files":4,"scraps":16},"airbattery":{"name":"iPhone Air 专用 MagSafe 电池：三代电池，改的是谁给谁充","label":{"zh":"MagSafe 电池 · Air","en":"iPhone Air MagSafe Battery"},"subject":"苹果的外接电池有三代：聪明电池壳（Smart Battery Case）、MagSafe 电池组（L 口）、以及这一块 iPhone Air 专用 MagSafe 电池（C 口）。三代之间真正变化的不是容量，而是**谁给谁充电**。这一期写机制，不写百分比——因为百分比这件事，作者自己就是怀疑的。","released":"2025-10","createdAt":"2025-09-22T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1222,"files":4,"scraps":16},"pm17":{"name":"形式追随功能的一代 · iPhone 17 Pro Max","label":{"zh":"iPhone 17 Pro Max","en":"iPhone 17 Pro Max"},"subject":"这一代 Pro 换了材质：从钛回到铝。文章要回答的不是「好不好看」，而是**为什么必须换**——铝的导热系数是钛的二十倍、密度是钛的三分之二，配上 VC 均热板，A19 Pro 的性能才有地方释放，减下来的重量又能换成更大的电池。这就是标题里的「形式追随功能」：外形是被功能逼出来的结果，不是审美的选择。","released":"2025-10","createdAt":"2025-10-04T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1313,"files":4,"scraps":16},"sympathy":{"name":"Project Sympathy：iPod 消失了，音乐没有","label":{"zh":"Project Sympathy","en":"Project Sympathy"},"subject":"一副降噪耳机和一台已经停产的播放器之间有什么关系？这一期把 AirPods Max 接回 iPod：pod 这个词出自《2001 太空漫游》，数字中枢时代 iPod 与 Mac 是分离舱与母舰，而今天的 AirPods 没有硬盘、不能同步，却可以串流。硬件换了一轮又一轮，被传承下来的是音乐这件事本身。","released":"2025-07","createdAt":"2024-09-19T12:00:00.000Z","exportedAt":"2026-09-23T17:45:00.000Z","words":1007,"files":4,"scraps":16},"ceramic":{"name":"陶瓷 Apple Watch：我的白月光","label":{"zh":"陶瓷 Apple Watch","en":"The Ceramic Apple Watch"},"subject":"白色精密陶瓷的一体表壳，是苹果最神秘的工艺之一：发布会一句带过，只在盒子里藏了一本讲工艺的书。它在 Series 2、3、5 上出现，2020 年退场；2026 年 9 月，Series 12 又把陶瓷带了回来，小米也同时推出了陶瓷特别版。","released":"2025-07","createdAt":"2025-07-15T12:00:00.000Z","exportedAt":"2026-09-24T23:00:00.000Z","words":1772,"files":4,"scraps":16},"macpro19":{"name":"大学时的白月光 · Mac Pro (2019)","label":{"zh":"Mac Pro 2019","en":"Mac Pro (2019)"},"subject":"一台五万起步、顶配四十万的塔式工作站，今天单核打不过最便宜的 M4 Mac mini，能效上是一台 1400W 的暖风机。那为什么还要收藏它？因为 macOS 26 Tahoe 是最后一个支持 Intel Mac 的大版本：往前，你可以用虚拟机一路回到 10.4 Tiger；往后，只剩 Apple 芯片。这台机器是苹果关门之前留下的那道门缝。","released":"2026-03","createdAt":"2025-10-23T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1557,"files":4,"scraps":16},"pocket":{"name":"当 iPhone 穿上三宅一生：一块布，一个口袋，你就是独一无二的你","label":{"zh":"iPhone Pocket","en":"iPhone Pocket"},"subject":"一千多块一条「袜子」，凭什么？这一期用三句话说清楚：一块布（三宅一生与乔布斯共有的那种「简单、耐穿、留出空间」的哲学）、一个口袋（苹果从 iPod Socks 一路走到今天的可穿戴配件线）、你就是独一无二的你（布料会被你的使用形塑，装什么、挂在哪、出现在哪张照片里，都不是苹果预先设计好的）。","released":"2025-11","createdAt":"2025-11-12T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1126,"files":4,"scraps":16},"iphone6sp":{"name":"还有人记得 3D Touch 吗 · iPhone 6s Plus","label":{"zh":"iPhone 6s Plus","en":"iPhone 6s Plus"},"subject":"一台十年前发布时被嫌「乏味」的手机，今天却是很多人记忆里最耐用的一台。这一期要从一台全新未拆封的 6s Plus 出发，讲三件事：它为什么耐用（A9 那管牙膏与 2GB 内存）、3D Touch 留下的遗产（层级与实感）、以及 Live Photos 把「时间」变成可以按下去的东西。结尾不吹参数，落在「器材只是工具」上。","released":"2025-08","createdAt":"2025-08-17T12:00:00.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1466,"files":4,"scraps":16},"sleeve":{"name":"MagSafe 皮革保护套：苹果是怎么看待手机依赖的？","label":{"zh":"MagSafe 皮革保护套","en":"MagSafe Leather Sleeve"},"subject":"苹果的手机很晚才有息屏显示，比三星晚六年，比自己的 Apple Watch 晚一千多天。iPhone 12 的 MagSafe 皮革保护套是这段历史的见证：它在一扇小窗里，提前两年把息屏显示的逻辑在 iPhone 上跑了一遍。它来自 2018 年「数字健康」的那个信念，假设你充电时不用手机；它没有下文，苹果后来的息屏显示也走了相反的路。","released":"2025-09","createdAt":"2025-09-05T12:00:00.000Z","exportedAt":"2026-09-25T00:00:00.000Z","words":1677,"files":4,"scraps":21},"pm12":{"name":"iPhone 12 Pro Max：开箱一台未激活的，还有苹果最奇葩的手机壳","label":{"zh":"iPhone 12 Pro Max","en":"iPhone 12 Pro Max"},"subject":"一台全新未激活的海蓝色 iPhone 12 Pro Max：电池亏电，靠人工抬电压救回来；系统停在 iOS 14.2.1，刚好能原汁原味地体验那个奇怪的 MagSafe 皮革保护套。开这台手机，是为了看那个壳：它不是不能接电话，而是不想让你把手机拿出来，可以理解成 iPhone 的一个 AOD 废案。","released":"2025-09","createdAt":"2025-09-05T12:00:00.000Z","exportedAt":"2026-09-25T00:00:00.000Z","words":1749,"files":4,"scraps":18},"pm11":{"name":"iPhone 11 Pro Max：我觉得最丑的一代 iPhone","label":{"zh":"iPhone 11 Pro Max","en":"iPhone 11 Pro Max"},"subject":"「如果要我选最丑的一代 iPhone，我觉得非 iPhone 11 系列莫属。」一台全新未拆封的美版有锁 iPhone 11 Pro Max，首发 iOS 13.0，没有 Deep Fusion，还留着后来被取消的「超取景框取景」。最后官方解锁成功，最丑的一台给了一个最完美的结局。","released":"2025-08","createdAt":"2025-08-01T22:06:47.000Z","exportedAt":"2026-09-24T23:30:00.000Z","words":2185,"files":4,"scraps":24},"m5mba":{"name":"M5 MacBook Air：这一次的牙膏，挤在硬盘上","label":{"zh":"M5 MacBook Air","en":"M5 MacBook Air"},"subject":"M5 MacBook Air 真正的升级不在芯片，而在内置存储第一次比外置又快又划算：在 SSD 涨价的背景下，「加钱买容量」第一次变成理性选择。而 Air 与 Pro 的分界，也从「性能」挪到了散热、屏幕和接口。","released":"2026-03","createdAt":"2026-03-16T10:06:27.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1315,"files":4,"scraps":16},"mbneo":{"name":"MacBook Neo：苹果把 iPhone 芯片放进 Mac 的那一天","label":{"zh":"MacBook Neo","en":"MacBook Neo"},"subject":"MacBook Neo 不是「便宜的 Mac」，是一次把取舍摊在明面上的公开课：4599／5299 的定价与面向学区的定位，决定了它砍掉哪几条线（P3、原彩、Force Touch、MagSafe、HDMI、背光键盘、快速充电），也决定了它保住哪几条线（A18 Pro 的单核、媒体引擎、神经引擎、无风扇）。这一期要讲清的是那张取舍表，不是跑分。","released":"2026-03","createdAt":"2026-02-24T03:20:33.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1352,"files":4,"scraps":17},"mini7":{"name":"iPad mini (A17 Pro)：每天跟着你出门的那一台","label":{"zh":"iPad mini A17 Pro","en":"iPad mini (A17 Pro)"},"subject":"iPad mini 不是「小一号的 iPad」，它是产品线里唯一把「内容消费」写在脸上的那一台：前置摄像头留在短边、8.3 寸接近单行本、297 克能塞进斜挎包。这一期要讲的是它的指标性意义——一台机器怎么用短边摄像头和 Slide Over 的进出，把苹果对 iPad 的定位说清楚。","released":"2025-12","createdAt":"2025-11-13T18:11:36.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1423,"files":4,"scraps":17},"mkb":{"name":"Magic Keyboard (USB-C)：确定性也是一种硬件规格","label":{"zh":"Magic Keyboard","en":"Magic Keyboard (USB-C)"},"subject":"一把 1399 元的薄膜键盘值不值，取决于你要的是「手感」还是「确定性」。它不和机械键盘比手感，它卖的是别人给不了的三件事：Touch ID 与系统的深度集成、地球键与菜单键这类只属于原厂的按键语义、以及「永远在那儿、不需要你操心」的确定性。副线是那 150 块的黑色差价的来历。","released":"2026-01","createdAt":"2026-01-12T02:19:59.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1368,"files":4,"scraps":17},"sd":{"name":"Studio Display：买断一份安心","label":{"zh":"Studio Display","en":"Studio Display"},"subject":"一块 60Hz、传统 IPS、600 尼特的显示器，为什么在 2026 年还占着桌面的 C 位。答案不在面板参数里，而在两件事：macOS 的点对点渲染让它成为一块「印刷品」，以及原厂把带宽、色彩、声音与系统功能都做成了不需要你操心的事。代价也很明确——对 PC、游戏与 HDR 刚需的人来说，它是一次昂贵的错配。","released":"2026-01","createdAt":"2025-12-08T17:12:12.000Z","exportedAt":"2026-09-24T00:30:00.000Z","words":1511,"files":4,"scraps":17},"ios19":{"name":"WWDC2099：苹果最诚实的标签","label":{"zh":"WWDC2099","en":"WWDC2099"},"subject":"一篇幕后工程视角的深度分析：不要从「谁的爆料更准」开始，而是把内部构建里散落的代号、标识符、Feature Flag 与 build 痕迹串成一条可复核的证据链，再看外媒叙事是怎么从这些碎片里被加工出来的。钉子只有一个字段：TargetRelease 里的占位符 **WWDC2099**。","released":"","createdAt":"2025-05-22T07:14:46.000Z","exportedAt":"2026-09-24T02:00:00.000Z","words":1354,"files":4,"scraps":16},"ipada4":{"name":"iPad Air 4 工程机：挖挖苹果内部的工程系统","label":{"zh":"iPad Air 4 工程机","en":"iPad Air 4 Prototype"},"subject":"一台没有屏幕的 iPad Air 4 工程机：先确认阶段，再把画面投出来，然后把整个工程系统拷贝下来，看看里面放了什么。最大的发现，是一个没人再用的测试 App 里，还留着一台苹果从未发布的 A8X iPad Pro。","released":"2025-05","createdAt":"2025-05-09T00:33:19.000Z","exportedAt":"2026-09-24T21:30:00.000Z","words":1727,"files":4,"scraps":13},"ip16p":{"name":"iPhone 16 工程机：竟然有未来产品的细节？","label":{"zh":"iPhone 16 工程机","en":"iPhone 16 Prototype"},"subject":"一台工程机的难点不在「拿到」，而在「接上」：它没有屏幕、禁用了密码登录、默认 16 位色深、跑着两套动态库缓存、还有 AMFI 挡在前面。把这几关拆开，就看清了两件事——每一道限制背后都有产线与保密的设计理由；而它真正值钱的地方，是让你在今天看到两三年后的计划。","released":"2025-06","createdAt":"2025-03-11T00:00:00.000Z","exportedAt":"2026-09-24T21:00:00.000Z","words":2429,"files":4,"scraps":19},"mgscrap":{"name":"MagSafe 废案：苹果怎么对待失败的作品","label":{"zh":"MagSafe 废案","en":"MagSafe Prototypes"},"subject":"AirPower 取消两个月后，一块磁极还是反着的 MagSafe 工程样品下线了。从承认失败到换一条路，苹果只用了半年；而今天的 Siri，从延期到重新登台用了一年多。这一期想说：苹果的问题不是没有创新，而是执行力。","released":"2025-06","createdAt":"2025-04-20T00:00:00.000Z","exportedAt":"2026-09-24T20:30:00.000Z","words":1917,"files":4,"scraps":15},"t2nic":{"name":"Apple T2 网卡：一块卡上的两台设备","label":{"zh":"T2 网卡","en":"Apple T2 Network Card"},"subject":"大家把它叫「苹果还出网卡？」，但这张卡的重点不在网卡那半。网卡部分是标准的 Mellanox，能刷原厂固件；真正的问题在另一半——一个只知道 Vendor ID 的设备。一块卡上为什么会有两台设备、苹果为什么要把它们绑在一起，这才是值得查的问题。","released":"","createdAt":"2025-05-07T09:55:51.000Z","exportedAt":"2026-09-24T06:00:00.000Z","words":1250,"files":4,"scraps":16},"airtrans":{"name":"透明探索版 Air：透明不是配色，是工作方法","label":{"zh":"透明 Air 工程机","en":"Transparent Air Prototypes"},"subject":"苹果做透明工程机，不是为了好看，而是为了让工程师看得见——外壳透明，里面的结构、上胶的位置、元件的排布就都能被观察。这些原型记录的是「定稿之前的样子」：尺寸会变、按钮后来才加、充电头的工艺也会一代代变干净。而这份习惯在今天是可见的：从彩色 iMac 到笔记本的内部布局，再到系统界面里把材质与层次做成设计语言。","released":"2025-12","createdAt":"2025-12-01T05:58:38.000Z","exportedAt":"2026-09-24T07:00:00.000Z","words":1395,"files":4,"scraps":15},"ip4sdemo":{"name":"iPhone 4S Demo：回到过去的钥匙","label":{"zh":"iPhone 4S 展示机","en":"iPhone 4S Demo Unit"},"subject":"一台背面写着「Demo - Not for resale」的全新展示机。它生来是为了被看见：躺在零售店的展示柜里循环播放。这一期从小处着手——用三个声音、一台未激活的机器、几款老游戏和一句冷静的引用，讲清「时间胶囊」为什么值得打开，而不是把它供在盒子里。","released":"2025-12","createdAt":"2025-09-29T09:46:58.000Z","exportedAt":"2026-09-24T20:00:00.000Z","words":2742,"files":4,"scraps":17},"airact":{"name":"iPhone Air：165 克本该是正常手机的重量","label":{"zh":"iPhone Air","en":"iPhone Air"},"subject":"这一代最激进的地方不是某个功能，而是它敢做减法：5.6 毫米、165 克、一整块玻璃配抛光钛边框。而它最容易被误读的地方也在这里——大家默认「薄必然牺牲续航」，实测却相反；真正的代价在接口、扬声器和相机上。换句话说，不是它太轻，是这些年我们把重量当成了常态。","released":"2025-09","createdAt":"2025-09-08T04:03:24.000Z","exportedAt":"2026-09-24T09:00:00.000Z","words":1496,"files":4,"scraps":16},"touch2":{"name":"touch 2 工程板：一块不是设备的设备","label":{"zh":"touch 2 工程板","en":"touch 2 Engineering Board"},"subject":"这块板子既是 iPod nano 4，也是 iPod touch 2——因为它根本不是一台设备，而是一个治具：它的使命是测试一颗芯片，而不是当一台播放器。没有序列号、跑不了 iOS、在产品发售之后还在继续工作。想回答「苹果怎么开发硬件」，这块板子就是最直接的物证。","released":"2025-08","createdAt":"2025-08-07T04:18:54.000Z","exportedAt":"2026-09-24T10:00:00.000Z","words":1339,"files":4,"scraps":15},"noport":{"name":"无接口 Apple Watch：先有安全网，才敢拆掉那个口","label":{"zh":"无接口 Apple Watch","en":"Portless Apple Watch"},"subject":"手表的诊断接口从实体针脚走到无线，表面上像一次「无孔化」的美学选择；但真正的推手是另一条线：设备必须能自己恢复。iCloud、网络恢复、无线调试、系统恢复、邻近设备恢复，这些能力一站一站补齐之后，苹果才敢把那个口拿掉——Series 7 去掉诊断口的同一年，恢复模式也补上了。","released":"2025-08","createdAt":"2025-08-26T12:31:30.000Z","exportedAt":"2026-09-24T11:00:00.000Z","words":1318,"files":4,"scraps":14},"cdma4":{"name":"CDMA 版 iPhone 4：最早的「国行 eSIM」iPhone","label":{"zh":"CDMA iPhone 4","en":"CDMA iPhone 4"},"subject":"这台十五年前的电信版 iPhone 4 没有卡槽，号码要去营业厅写进去，看起来像是「最早的国行 eSIM」。其实它是 eSIM 的反面：写号是机卡合一，eSIM 是机卡分离。只是国行 eSIM 在办理上，又走回了营业厅的柜台。","released":"2025-10","createdAt":"2025-10-14T08:02:00.000Z","exportedAt":"2026-09-24T22:30:00.000Z","words":1534,"files":4,"scraps":20},"iphone17":{"name":"iPhone 17 标准版：诚意不是心情，是价格行为","label":{"zh":"iPhone 17","en":"iPhone 17"},"subject":"这一代标准版第一次把 Pro 的东西给齐了：120Hz 高刷、256GB 起步、40W 快充，价格却停在上一代 128GB 的位置。所有人都在说「苹果今年有诚意」。本盘要问的是另一件事：这份诚意是从哪来的——它是心情，还是价格行为？","released":"2025-10","createdAt":"2025-09-09T17:00:00.000Z","exportedAt":"2026-09-24T13:00:00.000Z","words":2305,"files":4,"scraps":16},"windowshade":{"name":"收起窗口，留下位置：一个比 Mac 还老的双击","label":{"zh":"WindowShade","en":"WindowShade"},"subject":"WindowShade 的官网（首页与长文「窗口往事」）：一个 1994 年的双击，怎样从共享软件变成系统功能、被 Dock 送走、在便笺里留了一口气，又在 2026 年回到 Mac 上。不是产品说明书，是写给「窗口挤成一团就想关掉」的人的一篇长文。","released":"","createdAt":"2026-06-30T12:00:00.000Z","exportedAt":"2026-09-23T12:00:00.000Z","words":749,"files":4,"scraps":16},"ipadpro18":{"name":"A12X，桌面级性能的预演","label":{"zh":"iPad Pro 2018","en":"iPad Pro 2018"},"subject":"iPad Pro 2018 的 A12X，和它替 Mac 转向自研芯片做的那场预演。","released":"","createdAt":"2026-09-25T18:36:50.000Z","exportedAt":"2026-09-26T19:17:07.472Z","words":1637,"files":7,"scraps":15}};
window.AISystem6SharedProjectDisksIndexLoaded = true;

// The Project Hard Disks that ship with the application, at the two doors a
// person arrives through.
//
// The disks themselves are a Finder folder on the Startup Disk: a disk is a
// Finder object, so it gets Finder chrome -- count, view controls, selection
// and a double click that opens -- instead of a window with a private list and
// a private button. That page is markup (index.html) drawn from data
// (getDemonstrationDiskItems in app.js).
//
// Opening a disk here means looking inside it. A visitor from a video or a
// README comes to read, and a copy on this computer is a second, deliberate
// step, so a double click (or the space bar, the way Quick Look answers it)
// opens the disk's read-only window, app/features/disk-peek.js, and that
// window carries the button that makes the copy. A /go/<route> link still
// mounts its disk straight away: whoever shares one has already chosen it.
//
// What is left for this file is what the Finder cannot own: the rows and their
// columns, the keys that walk them, the command behind the File menu row and
// the Startup Disk row, and the copy of the list inside the Import Utility,
// where someone already choosing a backup file should see that ready-made
// disks exist.
//
// Why it ships here: tooling/build-shared-project-disks.mjs appends this file
// to the generated index module, so the first look at the disks costs the boot
// payload nothing and fetches ~20 KB of names rather than every manuscript.
// A backup loads when its disk is actually looked into or opened.

function installDemoDisksPanel() {
  const WINDOW_NAME = "projectDisks";
  const inlineSectionSelector = ".backup-preview-section";
  const inlineHostId = "demo-disks-inline";
  const mountKeyPrefix = "aiSystem6SharedDisk:";
  const SUBJECT_LIMIT = 96;

  function isZh() {
    return !(typeof currentLanguage === "string" && currentLanguage.startsWith("en"));
  }

  function t2(key, zh, en) {
    let value = "";
    try {
      value = typeof t === "function" ? t(key) : "";
    } catch {
      value = "";
    }
    if (!value || value === key) value = isZh() ? zh : en;
    return value;
  }

  function mountedProject(route) {
    let id = "";
    try {
      id = localStorage.getItem(mountKeyPrefix + route) || "";
    } catch {
      id = "";
    }
    if (!id) return null;
    const list = typeof projects !== "undefined" && Array.isArray(projects) ? projects : [];
    return list.find((project) => project.id === id) || null;
  }

  // A disk wears the object on it -- "iPhone 12 Pro Max" -- and the article
  // it holds is the second column, because thirty-five article titles folded
  // into six-line icon labels named nothing. The label comes from the disk
  // registry, in both languages.
  function diskLabel(disk, route) {
    const label = disk?.label || {};
    return (isZh() ? label.zh : label.en) || label.zh || disk?.name || route;
  }

  // The month the finished piece came out. The video folders record a month,
  // not a day, so a month is all the column claims; a disk written ahead of its
  // video has none and says so with the Finder's own blank.
  function releasedLabel(disk) {
    const match = /^(\d{4})-(\d{2})$/.exec(String(disk?.released || ""));
    return match ? `${match[1]}/${match[2]}` : "--";
  }

  function wordsLabel(disk) {
    return t("demo_disk_words", Number(disk?.words) || 0);
  }

  // Newest piece first; within a month, the project that began later; a disk
  // with no release yet goes after every one that has one.
  function orderedRoutes() {
    const index = window.AISystem6SharedProjectDisksIndex || {};
    return Object.keys(index).sort((a, b) => {
      const left = index[a] || {};
      const right = index[b] || {};
      return String(right.released || "").localeCompare(String(left.released || ""))
        || String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
    });
  }

  // The rows the Startup Disk's folder draws. They live here rather than in
  // app.js because this module is where the index they read arrives: the boot
  // bundle then carries one guarded call instead of a mapper for data it never
  // has. The folder's own page asks for them through the window manager, which
  // ensures this module first.
  function finderItems() {
    const index = window.AISystem6SharedProjectDisksIndex || {};
    return orderedRoutes().map((route) => {
      const disk = index[route] || {};
      const size = wordsLabel(disk);
      return {
        name: diskLabel(disk, route),
        iconId: "projectDisk",
        icon: "project-disk-icon",
        action: `look-shared-disk-${route}`,
        kind: t("project_disk"),
        description: disk.subject || "",
        sizeLabel: size,
        createdAt: disk.createdAt || disk.exportedAt || "",
        // Sorting by date follows the release month; a disk without one sorts
        // by the day its project began, which is the only date it has.
        updatedAt: disk.released ? `${disk.released}-01T00:00:00.000Z` : (disk.createdAt || ""),
        listCells: [disk.name || route, size, releasedLabel(disk)],
      };
    });
  }
  // The metadata every Finder item carries (built-in size, the folder as its
  // location, the description Get Info shows) is the boot bundle's helper, and
  // this module runs in the same scope, so the rows come back finished.
  window.AISystem6DemonstrationDiskItems = () => (
    typeof withStaticFinderMetadata === "function"
      ? withStaticFinderMetadata(finderItems(), t("demo_disks_title"))
      : finderItems()
  );
  // The list view's columns for this folder: kind and size say the same thing
  // on all thirty-five rows, so the columns carry what differs -- the article,
  // its length and when it came out. A function, so a language switch redraws
  // the headings with the rows.
  window.AISystem6FinderListHeads = {
    ...(window.AISystem6FinderListHeads || {}),
    [WINDOW_NAME]: () => [
      t("demo_disk_column_title"),
      t("demo_disk_column_words"),
      t("demo_disk_column_released"),
    ],
  };

  // One line per disk, straight from the generated index. The subject is the
  // writer's own first line under "## 主题", so a row cannot drift away from
  // what the project says about itself; a disk that has none falls back to what
  // the row actually is, two counts.
  function disks() {
    const index = window.AISystem6SharedProjectDisksIndex || {};
    return Object.keys(index).map((route) => ({ route, ...index[route] }));
  }

  function summary(disk) {
    const subject = String(disk?.subject || "").replace(/\s+/g, " ").trim();
    if (subject) return subject.length > SUBJECT_LIMIT ? `${subject.slice(0, SUBJECT_LIMIT)}…` : subject;
    const files = Number(disk?.files) || 0;
    const scraps = Number(disk?.scraps) || 0;
    return isZh() ? `${files} 个文件 · ${scraps} 条摘录` : `${files} files · ${scraps} excerpts`;
  }

  function button(label, handler) {
    const element = document.createElement("button");
    element.type = "button";
    element.className = "btn";
    element.textContent = label;
    element.addEventListener("click", handler);
    return element;
  }

  function rowFor(disk) {
    const row = document.createElement("div");
    // .import-row is icon | flexible label | trailing control, which is exactly
    // this row's shape. .backup-preview-row re-cut those columns for a preview
    // that carries no button, so it is not reused here: a fourth grid child
    // would fall out of its three columns.
    row.className = "import-row";
    const icon = document.createElement("span");
    icon.className = "mini-icon project-disk-icon";
    const label = document.createElement("span");
    const name = document.createElement("b");
    name.textContent = disk.name || disk.route;
    const line = document.createElement("small");
    // The row is one line, so the name and the subject need a mark between
    // them: without it the two read as one run-on word.
    line.textContent = ` · ${summary(disk)}`;
    label.append(name, line);
    row.append(icon, label);

    const here = Boolean(mountedProject(disk.route));
    row.append(button(
      here
        ? t2("demo_disk_open_existing", "打开已有的", "Open existing")
        : t2("demo_disk_open", "打开", "Open"),
      () => {
        if (typeof openSharedProjectDisk !== "function") return;
        Promise.resolve(openSharedProjectDisk(disk.route)).then(renderInline, renderInline);
      },
    ));
    return row;
  }

  function listFor(entries) {
    const list = document.createElement("div");
    list.className = "demo-disks-list";
    entries.forEach((entry) => list.append(rowFor(entry)));
    return list;
  }

  function inlineHost() {
    const section = document.querySelector(inlineSectionSelector);
    if (!section) return null;
    let host = document.getElementById(inlineHostId);
    if (!host) {
      host = document.createElement("div");
      host.id = inlineHostId;
      section.append(host);
    }
    return host;
  }

  // The Import Utility gets the rows and one line saying what they are, without
  // the folder's chrome: whoever is already in that window wants the disks, not
  // a second Finder page.
  function renderInline() {
    const host = inlineHost();
    if (!host) return;
    host.replaceChildren();
    const entries = disks();
    if (!entries.length) return;
    const blurb = document.createElement("p");
    blurb.className = "hint";
    blurb.textContent = t2(
      "demo_disks_blurb",
      "每块演示盘都是作者走完整条路线之后的现场。打开即在这台电脑上新建一份副本。",
      "Each demonstration disk is the site its writer left after walking the whole route. Opening one makes a copy on this computer.",
    );
    host.append(blurb, listFor(entries));
  }

  // The File menu row and the Startup Disk row both dispatch this. The command
  // is lazy (app/core/app-admissions.js names the loader), so a module that
  // fails to arrive greys the row and says why instead of opening an empty
  // folder; by the time this runs, the folder's rows are loaded.
  function open() {
    if (typeof openWindow !== "function") return;
    openWindow(WINDOW_NAME);
  }

  // Everything the Import Utility's copy shows is drawn from t() rather than
  // declared as data-i18n, so a language switch has to draw it again. The
  // folder itself repaints with the other Finder pages (app.js
  // finderContainerWindowNames); the name this hook is declared under lives on
  // the window's admission row, which persistence-status.js iterates.
  function renderDemoDisksPanel() {
    renderInline();
    window.AISystem6DiskPeek?.render?.();
  }
  window.renderDemoDisksPanel = renderDemoDisksPanel;

  // Looking inside a disk. The window is its own lazy module; this is the one
  // door to it, so a double click, the space bar and the /go/disks link all
  // arrive at the same place with the same disk.
  async function look(route) {
    if (!route || typeof ensureDiskPeekModule !== "function") return;
    await ensureDiskPeekModule();
    await window.AISystem6DiskPeek?.open?.(route, { from: rowElement(route) });
  }

  function rowElement(route) {
    return document.querySelector(
      `[data-window="${WINDOW_NAME}"] [data-static-finder-action="look-shared-disk-${route}"]`,
    );
  }

  function selectedRoute() {
    const item = typeof getSelectedStaticFinderItem === "function" ? getSelectedStaticFinderItem(WINDOW_NAME) : null;
    const match = /^look-shared-disk-([a-z0-9-]+)$/.exec(item?.action || "");
    return match ? match[1] : "";
  }

  // Select a disk in the folder the way a click would, and keep it in view. The
  // peek window calls this when its arrows walk the shelf, so the folder behind
  // it always shows which disk is being read.
  function selectRoute(route) {
    if (!route || typeof selectStaticFinderItem !== "function") return;
    selectStaticFinderItem(WINDOW_NAME, `look-shared-disk-${route}`);
    rowElement(route)?.scrollIntoView?.({ block: "nearest" });
  }

  // The newest finished piece: what /go/disks opens on, so a visitor arriving
  // from a video sees an article at once instead of thirty-five icons.
  async function openLatest() {
    if (typeof openWindow !== "function") return;
    await openWindow(WINDOW_NAME);
    const route = orderedRoutes()[0];
    if (!route) return;
    selectRoute(route);
    await look(route);
  }

  // Walking the folder with the keyboard. The Finder has no arrow keys of its
  // own, and this folder is the one place a person goes through items one by
  // one to read them, so the keys live with it. Icon view moves by a row with
  // up and down, list view by one; the space bar and Return look inside.
  function gridColumns() {
    const cells = [...document.querySelectorAll(`[data-window="${WINDOW_NAME}"] .finder-item`)];
    if (cells.length < 2) return 1;
    const top = cells[0].offsetTop;
    const index = cells.findIndex((cell) => cell.offsetTop !== top);
    return index === -1 ? cells.length : index;
  }

  function step(route, delta) {
    const routes = orderedRoutes();
    const at = routes.indexOf(route);
    if (at < 0) return routes[0] || "";
    return routes[Math.max(0, Math.min(routes.length - 1, at + delta))];
  }

  function onKeydown(event) {
    if (event.defaultPrevented || event.metaKey || event.ctrlKey || event.altKey) return;
    const active = document.querySelector(".window.is-active:not(.is-hidden)");
    if (active?.dataset.window !== WINDOW_NAME) return;
    if (document.querySelector(".menu.is-open")) return;
    if (typeof getActiveEditableElement === "function" && getActiveEditableElement()) return;
    const route = selectedRoute();
    const list = active.querySelector(".finder-list-row") !== null;
    const moves = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: list ? -1 : -gridColumns(),
      ArrowDown: list ? 1 : gridColumns(),
    };
    if (event.key in moves) {
      event.preventDefault();
      selectRoute(route ? step(route, moves[event.key]) : orderedRoutes()[0]);
      return;
    }
    if (event.key === " " || event.key === "Enter") {
      if (event.target?.closest?.("button, a, input, textarea, select") && !event.target.closest("[data-static-finder-action]")) return;
      event.preventDefault();
      const target = route || orderedRoutes()[0];
      selectRoute(target);
      look(target);
    }
  }
  document.addEventListener("keydown", onKeydown);

  window.AISystem6Runtime?.registerCommand?.("open-demo-disks", { handler: open, isAvailable: () => true });
  window.AISystem6Runtime?.registerCommand?.("open-demo-disks-latest", { handler: openLatest, isAvailable: () => true });
  Object.keys(window.AISystem6SharedProjectDisksIndex || {}).forEach((route) => {
    window.AISystem6Runtime?.registerCommand?.(`look-shared-disk-${route}`, { handler: () => look(route), isAvailable: () => true });
  });

  const section = document.querySelector(inlineSectionSelector);
  if (section) section.addEventListener("toggle", renderInline);
  renderInline();

  return Object.freeze({ open, openLatest, look, selectRoute, selectedRoute, step, orderedRoutes, diskLabel, releasedLabel, wordsLabel, renderInline, disks });
}

window.AISystem6DemoDisksPanel = installDemoDisksPanel();